{
  "originalFormula": "D_{n} \frac{\partial^2 \delta n}{\partial x^2} = 0, \\quad D_{p} \frac{\partial^2 \delta p}{\partial x^2} = 0",
  "genericFormula": "D_{n} \\frac{\\partial^2 \\delta n}{\\partial x^2} = 0, \\quad D_{p} \\frac{\\partial^2 \\delta p}{\\partial x^2} = 0",
  "description": "Esta fórmula representa a condição de equilíbrio de perturbações na densidade de portadores de carga em um semicondutor, onde a variação da densidade de elétrons e lacunas em relação à posição é analisada. A equação indica que, em um estado estacionário, não há variação espacial da densidade de portadores, ou seja, a densidade é uniforme ao longo da direção x.",
  "concepts": [
    "Densidade de portadores de carga",
    "Equilíbrio em semicondutores",
    "Derivadas parciais",
    "Condições de contorno em sistemas físicos"
  ],
  "symbols": [
    {
      "symbol": "D_{n}",
      "description": "Coeficiente de difusão dos elétrons, que indica a taxa de movimento dos elétrons em resposta a um gradiente de concentração."
    },
    {
      "symbol": "D_{p}",
      "description": "Coeficiente de difusão das lacunas, que representa a taxa de movimento das lacunas em resposta a um gradiente de concentração."
    },
    {
      "symbol": "\\delta n",
      "description": "Variação na densidade de elétrons, que representa a diferença na quantidade de elétrons em uma região específica em relação a um estado de equilíbrio."
    },
    {
      "symbol": "\\delta p",
      "description": "Variação na densidade de lacunas, que indica a diferença na quantidade de lacunas em uma região específica em relação a um estado de equilíbrio."
    },
    {
      "symbol": "x",
      "description": "A coordenada espacial ao longo da qual a densidade de portadores está sendo analisada."
    },
    {
      "symbol": "\\frac{\\partial^2}{\\partial x^2}",
      "description": "A derivada parcial de segunda ordem em relação à coordenada x, que mede como a variação da densidade de portadores muda em relação à posição."
    }
  ]
}
